// 把 RLE 结构放进世界
function placeStructure(s, ox, baseY, oz) {
  var dirty = {};
  function ec(cx, cz) {
    var k = ckey(cx, cz);
    if (!chunks[k]) chunks[k] = { data: genTerrain(cx, cz), mesh: null };
  }
  function raw(wx, wy, wz, id) {
    if (wy < 0 || wy >= CHUNK_H) return;
    var cx = Math.floor(wx / CHUNK_W);
    var cz = Math.floor(wz / CHUNK_D);
    ec(cx, cz);
    var ch = chunks[ckey(cx, cz)];
    var lx = ((wx % CHUNK_W) + CHUNK_W) % CHUNK_W;
    var lz = ((wz % CHUNK_D) + CHUNK_D) % CHUNK_D;
    ch.data[lx + wy * CHUNK_W + lz * CHUNK_W * CHUNK_H] = id;
    dirty[ckey(cx, cz)] = [cx, cz];
    if (lx === 0)         { ec(cx-1,cz); dirty[ckey(cx-1,cz)] = [cx-1,cz]; }
    if (lx === CHUNK_W-1) { ec(cx+1,cz); dirty[ckey(cx+1,cz)] = [cx+1,cz]; }
    if (lz === 0)         { ec(cx,cz-1); dirty[ckey(cx,cz-1)] = [cx,cz-1]; }
    if (lz === CHUNK_D-1) { ec(cx,cz+1); dirty[ckey(cx,cz+1)] = [cx,cz+1]; }
  }
  var oy = baseY - s.groundY;
  var i, j, id, n, x = 0, z = 0, y = 0;
  var rle = s.rle;
  for (i = 0; i < rle.length; i += 2) {
    id = rle[i]; n = rle[i+1];
    for (j = 0; j < n; j++) {
      if (!(id === AIR && y < s.groundY)) raw(ox + x, oy + y, oz + z, id);
      x++; if (x === s.w) { x = 0; z++; if (z === s.d) { z = 0; y++; } }
    }
  }
  var k, cd;
  for (k in dirty) { cd = dirty[k]; rebuildChunk(cd[0], cd[1]); }
}

// ── 简易城堡（美化版）────────────────────────────────────────────────────────
// 22×22 脚印，COBBLE/GRAY_BRICK/WHITE_STONE/RED_PILLAR 混用；
// 城墙 6 高，带交替垛口；四角瞭望塔 3×3×9，顶放 GRAY_ROOF 尖顶；
// 南门 3 宽 5 高，两侧 RED_PILLAR 门柱；内部铺灰砖，正中白石路；
// 北侧石砌主楼 10×7，双层，GRAY_ROOF 尖顶；广场中有 WHITE_STONE 水井圈；
// 城堡正中放领地石激活 R=25 结界。
function placeSimpleCastle(ox, oz) {
  var BY = SEA + 2;
  var dirty = {};

  function ec(cx, cz) {
    var k = ckey(cx, cz);
    if (!chunks[k]) chunks[k] = { data: genTerrain(cx, cz), mesh: null };
  }
  function raw(wx, wy, wz, id) {
    if (wy < 0 || wy >= CHUNK_H) return;
    var cx = Math.floor(wx / CHUNK_W), cz = Math.floor(wz / CHUNK_D);
    ec(cx, cz);
    var ch = chunks[ckey(cx, cz)];
    var lx = ((wx % CHUNK_W) + CHUNK_W) % CHUNK_W;
    var lz = ((wz % CHUNK_D) + CHUNK_D) % CHUNK_D;
    ch.data[lx + wy * CHUNK_W + lz * CHUNK_W * CHUNK_H] = id;
    dirty[ckey(cx, cz)] = [cx, cz];
    if (lx === 0)         { ec(cx-1,cz); dirty[ckey(cx-1,cz)] = [cx-1,cz]; }
    if (lx === CHUNK_W-1) { ec(cx+1,cz); dirty[ckey(cx+1,cz)] = [cx+1,cz]; }
    if (lz === 0)         { ec(cx,cz-1); dirty[ckey(cx,cz-1)] = [cx,cz-1]; }
    if (lz === CHUNK_D-1) { ec(cx,cz+1); dirty[ckey(cx,cz+1)] = [cx,cz+1]; }
  }

  var x, z, y;
  var W = 22, WALL_H = 6, TOWER_H = 9;

  // ── 平整场地（必须最先做）────────────────────────────────────────────────
  // 城堡在出生平地（半径 64 格混合带）之外的纯丘陵区，AMP=14 的山丘会横穿城墙。
  // 脚印 + 2 格裙边：地下填实地基（噪声谷底可低至 y≈0），上方清到丘陵最高点之上。
  var M = 2;
  for (x = -M; x < W + M; x++) {
    for (z = -M; z < W + M; z++) {
      raw(ox+x, BY, oz+z, GRASS);                              // 地表（内部稍后覆盖灰砖）
      for (y = BY - 4; y < BY; y++)  raw(ox+x, y, oz+z, DIRT);  // 浅层泥土
      for (y = 1; y < BY - 4; y++)   raw(ox+x, y, oz+z, STONE); // 深层石头地基
      for (y = BY + 1; y <= SEA + AMP + 2; y++) raw(ox+x, y, oz+z, AIR);  // 清空山体
    }
  }

  // ── 庭院地面 ──────────────────────────────────────────────────────────────
  for (x = 1; x < W-1; x++) {
    for (z = 1; z < W-1; z++) {
      raw(ox+x, BY, oz+z, GRAY_BRICK);
    }
  }
  // 中央白石路（南北向，城门 → 主楼门口）
  for (z = 2; z < W-3; z++) {
    raw(ox+10, BY, oz+z, WHITE_STONE);
    raw(ox+11, BY, oz+z, WHITE_STONE);
  }

  // ── 四面城墙（6 高 + 交替垛口）──────────────────────────────────────────
  for (y = 0; y < WALL_H; y++) {
    for (x = 0; x < W; x++) {
      raw(ox+x, BY+y, oz,     COBBLE);  // 北墙
      // 南墙：城门开口（x=9,10,11，高度 0-4）
      if (y < 5 && (x === 9 || x === 10 || x === 11)) {
        // 门洞，不放
      } else {
        raw(ox+x, BY+y, oz+W-1, COBBLE);
      }
    }
    for (z = 1; z < W-1; z++) {
      raw(ox,     BY+y, oz+z, COBBLE);  // 西墙
      raw(ox+W-1, BY+y, oz+z, COBBLE);  // 东墙
    }
  }
  // 城墙顶部垛口（交替凸凹，偶数格放方块）
  for (x = 0; x < W; x++) {
    if (x % 2 === 0) {
      raw(ox+x, BY+WALL_H, oz,     COBBLE);
      raw(ox+x, BY+WALL_H, oz+W-1, COBBLE);
    }
  }
  for (z = 1; z < W-1; z++) {
    if (z % 2 === 0) {
      raw(ox,     BY+WALL_H, oz+z, COBBLE);
      raw(ox+W-1, BY+WALL_H, oz+z, COBBLE);
    }
  }
  // 城门两侧 RED_PILLAR 门柱（全高）
  for (y = 0; y < WALL_H + 1; y++) {
    raw(ox+8,  BY+y, oz+W-1, RED_PILLAR);
    raw(ox+12, BY+y, oz+W-1, RED_PILLAR);
  }
  // 城门横梁（WHITE_STONE 门楣）
  raw(ox+9,  BY+5, oz+W-1, WHITE_STONE);
  raw(ox+10, BY+5, oz+W-1, WHITE_STONE);
  raw(ox+11, BY+5, oz+W-1, WHITE_STONE);

  // ── 四角瞭望塔（3×3，9 高，顶放 GRAY_ROOF）──────────────────────────────
  var corners = [[0,0],[W-3,0],[0,W-3],[W-3,W-3]];
  var ti;
  for (ti = 0; ti < corners.length; ti++) {
    var tx = corners[ti][0], tz = corners[ti][1];
    for (y = 0; y < TOWER_H; y++) {
      for (x = 0; x < 3; x++) {
        for (z = 0; z < 3; z++) {
          raw(ox+tx+x, BY+y, oz+tz+z, y < 6 ? COBBLE : GRAY_BRICK);
        }
      }
    }
    // 塔顶：GRAY_ROOF 尖顶 + 四角小垛口
    raw(ox+tx+1, BY+TOWER_H,   oz+tz+1, GRAY_ROOF);  // 中心尖顶
    raw(ox+tx,   BY+TOWER_H,   oz+tz,   COBBLE);
    raw(ox+tx+2, BY+TOWER_H,   oz+tz,   COBBLE);
    raw(ox+tx,   BY+TOWER_H,   oz+tz+2, COBBLE);
    raw(ox+tx+2, BY+TOWER_H,   oz+tz+2, COBBLE);
  }

  // ── 北侧主楼（10×7，双层，白石上层，灰屋顶尖）────────────────────────────
  var kox = ox+6, koz = oz+2;
  // 下层（STONE 外墙 + PLANKS 地板），高 5
  for (y = 0; y < 5; y++) {
    for (x = 0; x < 10; x++) {
      for (z = 0; z < 7; z++) {
        if (x === 0 || x === 9 || z === 0 || z === 6) raw(kox+x, BY+y, koz+z, STONE);
      }
    }
  }
  for (x = 1; x < 9; x++) {
    for (z = 1; z < 6; z++) raw(kox+x, BY, koz+z, PLANKS);
  }
  // 上层（WHITE_STONE 外墙），高 3
  for (y = 5; y < 8; y++) {
    for (x = 0; x < 10; x++) {
      for (z = 0; z < 7; z++) {
        if (x === 0 || x === 9 || z === 0 || z === 6) raw(kox+x, BY+y, koz+z, WHITE_STONE);
      }
    }
  }
  // 楼顶 GRAY_BRICK 封顶 + 中央 GRAY_ROOF 尖顶两块
  for (x = 0; x < 10; x++) {
    for (z = 0; z < 7; z++) raw(kox+x, BY+8, koz+z, GRAY_BRICK);
  }
  raw(kox+4, BY+9, koz+3, GRAY_ROOF);
  raw(kox+5, BY+9, koz+3, GRAY_ROOF);
  // 主楼南面门洞（3 宽 4 高，面向广场）
  for (y = 0; y < 4; y++) {
    raw(kox+4, BY+y, koz+6, AIR);
    raw(kox+5, BY+y, koz+6, AIR);
    raw(kox+6, BY+y, koz+6, AIR);
  }
  // 门口两侧 RED_PILLAR 柱
  for (y = 0; y < 5; y++) {
    raw(kox+3, BY+y, koz+6, RED_PILLAR);
    raw(kox+7, BY+y, koz+6, RED_PILLAR);
  }

  // ── 广场中心水井（5×5 WHITE_STONE 圈，高 1）──────────────────────────────
  for (x = 8; x <= 13; x++) {
    raw(ox+x, BY+1, oz+14, WHITE_STONE);
    raw(ox+x, BY+1, oz+18, WHITE_STONE);
  }
  for (z = 15; z <= 17; z++) {
    raw(ox+8,  BY+1, oz+z, WHITE_STONE);
    raw(ox+13, BY+1, oz+z, WHITE_STONE);
  }

  // ── 广场四盏石柱路灯（城门内侧两侧 + 主楼门口两侧）────────────────────────
  raw(ox+7,  BY+1, oz+W-3, RED_PILLAR);
  raw(ox+14, BY+1, oz+W-3, RED_PILLAR);
  raw(ox+7,  BY+1, oz+9,   RED_PILLAR);
  raw(ox+14, BY+1, oz+9,   RED_PILLAR);

  // ── 城堡广场中心 + 南门外集结点（供招兵系统使用）──────────────────────────
  _castleCourtyard = { x: ox + 11, z: oz + 15 };
  _castleGatePos   = { x: ox + 10.5, z: oz + W + 2 };  // 南门外 2 格

  // 领地石放于广场中心，激活 R=25 结界
  raw(ox+11, BY+1, oz+11, TERRITORY_STONE);
  if (typeof _addTerritory === 'function') _addTerritory(ox+11, BY+1, oz+11);

  var k, cd;
  for (k in dirty) { cd = dirty[k]; rebuildChunk(cd[0], cd[1]); }
}

// 敌人要塞：16×16 围墙院落，中心放置领主石（OBSIDIAN）
var _enemyStrongholdPos = null;

function placeEnemyStronghold(ox, oz) {
  var flatY = SEA + 2;  // 目标地表高度 = 14
  var W = 16, H = 4;
  var x, z, y;
  var dirty = {};

  function ec(cx, cz) {
    var k = ckey(cx, cz);
    if (!chunks[k]) chunks[k] = { data: genTerrain(cx, cz), mesh: null };
  }
  function raw(wx, wy, wz, id) {
    if (wy < 0 || wy >= CHUNK_H) return;
    var cx = Math.floor(wx / CHUNK_W), cz = Math.floor(wz / CHUNK_D);
    ec(cx, cz);
    var ch = chunks[ckey(cx, cz)];
    var lx = ((wx % CHUNK_W) + CHUNK_W) % CHUNK_W;
    var lz = ((wz % CHUNK_D) + CHUNK_D) % CHUNK_D;
    ch.data[lx + wy * CHUNK_W + lz * CHUNK_W * CHUNK_H] = id;
    dirty[ckey(cx, cz)] = [cx, cz];
    if (lx === 0)         { ec(cx-1,cz); dirty[ckey(cx-1,cz)] = [cx-1,cz]; }
    if (lx === CHUNK_W-1) { ec(cx+1,cz); dirty[ckey(cx+1,cz)] = [cx+1,cz]; }
    if (lz === 0)         { ec(cx,cz-1); dirty[ckey(cx,cz-1)] = [cx,cz-1]; }
    if (lz === CHUNK_D-1) { ec(cx,cz+1); dirty[ckey(cx,cz+1)] = [cx,cz+1]; }
  }

  // 平整地形（含 2 格边距）
  for (x = ox - 2; x < ox + W + 2; x++) {
    for (z = oz - 2; z < oz + W + 2; z++) {
      for (y = flatY + 1; y < flatY + 24; y++) raw(x, y, z, AIR); // 削山
      for (y = flatY - 6; y < flatY; y++) {                         // 填谷
        if (getBlock(x, y, z) === AIR) raw(x, y, z, DIRT);
      }
      raw(x, flatY, z, GRASS);  // 统一地表
    }
  }

  // 地面铺 GRAY_BRICK
  for (x = ox; x < ox + W; x++) {
    for (z = oz; z < oz + W; z++) {
      raw(x, flatY, z, GRAY_BRICK);
    }
  }

  // 四面围墙（COBBLE，高 H 格），南面留 2 格入口
  for (x = ox; x < ox + W; x++) {
    for (y = 1; y <= H; y++) {
      raw(x, flatY + y, oz, COBBLE);
      if (x < ox + 7 || x > ox + 8) raw(x, flatY + y, oz + W - 1, COBBLE);
    }
  }
  for (z = oz; z < oz + W; z++) {
    for (y = 1; y <= H; y++) {
      raw(ox,         flatY + y, z, COBBLE);
      raw(ox + W - 1, flatY + y, z, COBBLE);
    }
  }

  // 四角塔楼（STONE，高 H+2）
  var corners = [[ox,oz],[ox+W-2,oz],[ox,oz+W-2],[ox+W-2,oz+W-2]];
  corners.forEach(function(c) {
    for (y = 1; y <= H + 2; y++) {
      raw(c[0],   flatY + y, c[1],   STONE);
      raw(c[0]+1, flatY + y, c[1],   STONE);
      raw(c[0],   flatY + y, c[1]+1, STONE);
      raw(c[0]+1, flatY + y, c[1]+1, STONE);
    }
  });

  // 中心领主石（OBSIDIAN，高出地面 2 格，3×3 台座）
  var lcx = ox + 7, lcz = oz + 7;
  for (x = lcx - 1; x <= lcx + 1; x++) {
    for (z = lcz - 1; z <= lcz + 1; z++) {
      raw(x, flatY + 1, z, STONE);
    }
  }
  raw(lcx, flatY + 2, lcz, OBSIDIAN);

  // 守卫岗位（约 55 个固定站位）
  var posts = [], ri, rj;
  for (ri = 2; ri <= 13; ri += 2) { posts.push([1, ri]); posts.push([14, ri]); }  // 西+东墙内侧 12
  for (ri = 2; ri <= 13; ri += 2) posts.push([ri, 1]);                            // 北墙 6
  for (ri = 2; ri <= 13; ri += 2) { if (ri < 6 || ri > 9) posts.push([ri, 14]); }// 南墙（跳过门）4
  posts.push([6,13]); posts.push([7,13]); posts.push([8,13]); posts.push([9,13]); // 城门口 4
  posts.push([1,1]); posts.push([14,1]); posts.push([1,14]); posts.push([14,14]); // 四角 4
  for (ri = 5; ri <= 9; ri++) { posts.push([ri, 5]); posts.push([ri, 9]); }       // 领主石外环 10
  for (ri = 6; ri <= 8; ri++) { posts.push([5, ri]); posts.push([9, ri]); }       // 领主石侧环 6
  for (ri = 3; ri <= 11; ri += 4) {                                                // 内部网格 9
    for (rj = 3; rj <= 11; rj += 4) posts.push([ri, rj]);
  }
  // 总计 55 岗位

  // 重建区块网格（批量，每块只重建一次）
  var k, cd; for (k in dirty) { cd = dirty[k]; rebuildChunk(cd[0], cd[1]); }

  _enemyStrongholdPos = { x: lcx, y: flatY + 2, z: lcz, ox: ox, oz: oz, posts: posts };
}

// 启动时调用：围绕出生地布置中式建筑村落
function placeStructures() {
  var BY = SEA + 2;   // 平地地表 = 14
  placeStructure(STRUCT_TEMPLE, -20, BY, -57);   // 寺庙·正北
  placeStructure(STRUCT_PAGODA, -62, BY, -53);   // 宝塔·西北
  placeStructure(STRUCT_HOUSE, 28, BY, -28);   // 小屋·东北
  placeStructure(STRUCT_APOTHECARY, -10, BY, 35);   // 药铺·正南
  placeStructure(STRUCT_CAMP, 55, BY, 20);   // 营地·东南
  placeStructure(STRUCT_TULOU, 30, BY, -90);   // 土楼·远东北
  placeStructure(STRUCT_FORT, -90, BY, -90);   // 堡垒·远西北
  placeStructure(STRUCT_TOMB, 10, BY, 90);   // 皇陵·远南
  placeEnemyStronghold(100, 80);              // 敌人城池·东南方向约 128 格
}
